entries[86544] = { ["name"] = "Spinefish Alpha", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Fishing (1)\n\"Careful of the spines, they look like they could do some damage.\"" }
entries[86545] = { ["name"] = "Mimic Octopus", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Fishing (1)\n\"Even in death, this strange creature continues changing color to blend in with its environment.\"" }
entries[86546] = { ["name"] = "Sky Crystal", ["text"] = "Binds when picked up\nUnique\nUse: Remove the cloudy protections of Alani the Stormborn." }
entries[86547] = { ["name"] = "Skyshard", ["text"] = "Binds to Warband\nUnique (10)\nUse: Combine 10 Skyshards to create a Sky Crystal." }
entries[86550] = { ["name"] = "Apprentice Cookbook", ["text"] = "Binds to Warband\nUse: Test\nSell Price:" }
entries[86551] = { ["name"] = "Expert Cookbook", ["text"] = "Binds to Warband\nUse: Test\nSell Price:" }
entries[86552] = { ["name"] = "Artisan Cookbook", ["text"] = "Binds to Warband\nUse: Test\nSell Price:" }
entries[86553] = { ["name"] = "Master Cookbook", ["text"] = "Binds to Warband\nUse: Test\nSell Price:" }
entries[86554] = { ["name"] = "Grand Master Cookbook", ["text"] = "Binds to Warband\nUse: Test\nSell Price:" }
entries[86558] = { ["name"] = "Rolling Pin", ["text"] = "Binds to Warband\nUnique\nHeld In Off-hand\nEquip: +10 Pandaria Cooking Skill.\n\nTradition of Cooking (0/3) Apron\nFrying Pan\nRolling Pin\n(3) Set : +10 Pandaria Cooking Skill.\nSell Price:" }
entries[86559] = { ["name"] = "Frying Pan", ["text"] = "Binds to Warband\nUnique\nOne-Hand\n1 Damage Speed 2.00\n(0.5 damage per second)\nEquip: +10 Pandaria Cooking Skill.\n\nTradition of Cooking (0/3) Apron\nFrying Pan\nRolling Pin\n(3) Set : +10 Pandaria Cooking Skill.\nSell Price:" }
entries[86562] = { ["name"] = "Hopling", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss the Hopling.\nRequires level 1 to 80 ( 80)" }
entries[86563] = { ["name"] = "Hollow Reed", ["text"] = "Binds when picked up\nUse: Teaches you how to summon an Aqua Strider.\nRight Click to summon and dismiss the Aqua Strider.\nRequires level 1 to 80 ( 80)" }
entries[86564] = { ["name"] = "Imbued Jade Fragment", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to summon Grinder.\nRight Click to summon and dismiss Grinder.\nRequires level 1 to 80 ( 80)" }
entries[86565] = { ["name"] = "Battle Horn", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Blast a blaring horn, attracting enemies within 40 yards. Ineffective on targets above level 49 or not native to Pandaria. (2 Min Cooldown)\n\"Carried by Yaungol scouts to alert allies to impending attacks.\"" }
entries[86566] = { ["name"] = "Forager's Gloves", ["text"] = "Binds when picked up\nUnique\nHands Cloth\n1 Armor\nDurability 20 / 20\nEquip: Allows faster gathering of resources in Pandaria.\n\"Protects against sharp rocks and thorns.\"" }
entries[86567] = { ["name"] = "Yaungol Wind Chime", ["text"] = "Binds when picked up\nUnique\nTrinket\nUse: Charge at an enemy, inflicting 32 Physical damage to enemies within 8 yards and knocking them down for 2 sec. (2 Min Cooldown)\n\"Used by Yaungol medicine men to detect changes in the weather.\"\nSell Price:" }
entries[86568] = { ["name"] = "Mr. Smite's Brass Compass", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Release the memories of a long-lost first mate. (Proc chance: 5%, 3m cooldown) (2 Hrs Cooldown)" }
entries[86569] = { ["name"] = "Crystal of Insanity", ["text"] = "Binds when picked up\nUnique\nUse: Increases all stats by 9 for 1 hour. Counts as both a Battle and Guardian elixir. (15 Min Cooldown)\n\"Almost seems to be staring back at you.\"" }
entries[86570] = { ["name"] = "Crate of Kidnapped Puppies", ["text"] = "Binds when picked up\nUnique\nTrinket\nUse: Releases the kidnapped puppies to fight for you for 10 min. (1 Hour Cooldown)\n\"...and they eat puppies!\"\nSell Price:" }
entries[86571] = { ["name"] = "Kang's Bindstone", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Become infused with stone, granting a chance upon killing an opponent to encase them in stone. (Proc chance: 33%, 1m cooldown) (1 Hour Cooldown)\n\"Mogu stonebinders use these rune-etched catalysts to transform flesh to stone.\"" }
entries[86572] = { ["name"] = "Terracotta Fragment", ["text"] = "Binds when picked up\nUnique\nTrinket\nUse: Summons a Terracotta Warrior to fight for you for 10 min. (1 Hour Cooldown)\n\"Imbued with powerful Mogu magic.\"\nSell Price:" }
entries[86573] = { ["name"] = "Shard of Archstone", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Transform into a Mogu statue, becoming untargetable for 5 min. (30 Min Cooldown)\n\"A fragment of unknown origin, seething with ancient power.\"" }
entries[86574] = { ["name"] = "Elixir of Ancient Knowledge", ["text"] = "\"A faint whispering can be heard from the bottle.\"\nSell Price:" }
entries[86575] = { ["name"] = "Chalice of Secrets", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Give in to your anger for 10 sec. While active, the next killing blow made against a player will transform you into a Mogu for 6.3 sec, preventing any actions from being taken while you gloat. (10 Min Cooldown)\n\"The rituals for desecrating a fallen opponent are a well-established part of Mogu culture.\"" }
entries[86576] = { ["name"] = "Dynasty of Steel", ["text"] = "Binds when picked up\nUnique\nTrinket\nUse: Summons a Whirlwind of Blades to fight for you for 10 min. (1 Hour Cooldown)\n\"The sword techniques of the Mantid are a carefully-guarded secret.\"\nSell Price:" }
entries[86577] = { ["name"] = "Rod of Ambershaping", ["text"] = "Binds when picked up\nUnique\nUse: Encases the target in amber, preventing all action for up to 1 min. Any damage caused will break the amber. Does not work on players or targets above level 49. (5 Min Cooldown)\n\"Used by mantid amberweavers to spin structures of hardened amber.\"" }
entries[86578] = { ["name"] = "Eternal Warrior's Sigil", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Restores 15% of health and mana every 1 sec. for 6 sec. Any damage taken will remove the frenzy. Can only be used in Pandaria. (5 Min Cooldown)\n\"Granted to Shek'zeer's elite guard for service to the Empress.\"" }
entries[86579] = { ["name"] = "Bottled Tornado", ["text"] = "Binds when picked up\nUnique\nTrinket\n\"The Mantid learned long ago how to bend the winds of Pandaria to the Empress' will.\"\nSell Price:" }
entries[86580] = { ["name"] = "Wilted Lilypad", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior , Paladin , Hunter , Rogue , Priest , Death Knight , Shaman , Mage , Warlock , Monk\n\"Climate change has dried up this specimen.\"\nSell Price:" }
entries[86581] = { ["name"] = "Farwater Conch", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Allows you to see far into the distance and grants the ability to create small water droplets. (10 Min Cooldown)\n\"Inscribed with Jinyu runes that allow the user to understand the language of the waves.\"" }
entries[86582] = { ["name"] = "Aqua Jewel", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Increases swim speed by 50% and allows underwater breathing for 10 min. Only usable on Pandaria. (1 Hour Cooldown)\n\"Harvested from the maw of Gokk'lok.\"" }
entries[86583] = { ["name"] = "Salyin Battle Banner", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Blend into the shadows for 1 sec and summon a Salyin Warscout. The Warscout will draw the attention of nearby monsters and run into the distance. Only effective in Pandaria. (10 Min Cooldown)\n\"Stained with the blood of many unlucky adventurers.\"" }
entries[86584] = { ["name"] = "Hardened Shell", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Throw a hard shell, dismounting the target. Unusable on targets above level 49. (15 Min Cooldown)\n\"Seems unfair.\"" }
entries[86585] = { ["name"] = "Golden Fleece", ["text"] = "Binds when picked up\nUnique\nTrinket\nEquip: May cause extra gold to drop whenever you kill a target that yields experience or honor. (Proc chance: 10%, 10m cooldown)\n\"Considered a sign of wealth and status amongst the Saurok.\"\nSell Price:" }
entries[86586] = { ["name"] = "Panflute of Pandaria", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Play the panflute, causing nearby critters to follow you for 15 min. (1 Min Cooldown)" }
entries[86587] = { ["name"] = "Seed of Tranquil Growth", ["text"] = "Binds when picked up\nUnique\nTrinket\nUse: Summons a Tranquil Spout to heal you for 10 min. (1 Hour Cooldown)\n\"A vibrant life energy emanates from this seed.\"\nSell Price:" }
entries[86588] = { ["name"] = "Pandaren Firework Launcher", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Set up a dazzling firework display. (30 Min Cooldown)\n\"Party over here!\"" }
entries[86589] = { ["name"] = "Ai-Li's Skymirror", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Take on the slightly shimmery appearance of the target for 10 min. (1 Hour Cooldown)\n\"Rimmed with an ever-shifting ring of clouds.\"" }
entries[86590] = { ["name"] = "Essence of the Breeze", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Unleash a gentle breeze, lightening your steps. This effect only works in Pandaria. (1 Hour Cooldown)" }
entries[86591] = { ["name"] = "Magic Banana", ["text"] = "Binds when picked up\nUnique\nUse: Toss a magic banana on the ground, which will trip up the first person to walk over it. (2 Hrs Cooldown)" }
entries[86592] = { ["name"] = "Hozen Peace Pipe", ["text"] = "Use: Increases reputation with the denizens of Pandaria by 1000. (7 Days Cooldown)" }
entries[86593] = { ["name"] = "Hozen Beach Ball", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Get ready for fun in the sun! (1 Hour Cooldown)" }
entries[86594] = { ["name"] = "Helpful Wikky's Whistle", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Calls Helpful Wikky, who will forage for you and bring back presents. Can only be used in Pandaria. (2 Hrs Cooldown)\n\"Appears to have been heavily chewed on.\"" }
entries[86595] = { ["name"] = "Bag of Helpful Things", ["text"] = "Binds when picked up\nUnique\n<Right Click to Open>" }
entries[86596] = { ["name"] = "Nat's Fishing Chair", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Set up a comfy fishing chair. (5 Min Cooldown)\n\"It even has a beverage holder!\"" }
entries[86597] = { ["name"] = "Living Steel Weapon Chain", ["text"] = "Binds when equipped\nUse: Attaches a chain to your weapon, reducing the duration of Disarm effects by 50% and increasing your critical strike by 13. Does not stack with other similar effects. Attaching the weapon chain causes the weapon to become soulbound. Cannot be applied to items higher than level 320." }
entries[86598] = { ["name"] = "Vor'thik Eggs", ["text"] = "Quest Item" }
entries[86599] = { ["name"] = "Ghost Iron Shield Spike", ["text"] = "Binds when equipped\nUse: Attaches a ghost iron spike to your shield that sometimes deals 42 damage when you block with it.\n\nAttaching a ghost iron spike to your shield causes it to become soulbound. Cannot be applied to items higher than level 320.\nSell Price:" }
entries[86607] = { ["name"] = "Goblin Dragon Gun, Mark II", ["text"] = "Use: Unleash a gout of lightning, dealing 48 Nature damage to targets in a 10 yard cone in front of the caster every 0.5 sec for 4 sec.\n\nMay walk while casting. (30 Sec Cooldown)\n50 Charges\nSell Price:" }
entries[86616] = { ["name"] = "Dread Amber Focus", ["text"] = "Quest Item\n\"Concentrated fear bound in crystallized kypari sap.\"" }
entries[86623] = { ["name"] = "Blingtron 4000 Gift Package", ["text"] = "Binds when picked up\nUnique\n\"What are you waiting for? OPEN IT!\"\n<Right Click to Open>" }
entries[86624] = { ["name"] = "Firebird's Spaulders", ["text"] = "Raid Finder\nBinds when picked up\nShoulder Mail\n7 Armor\n+2 [Agility or Intellect]\n+5 Stamina\n+ 3 Critical Strike\n+ 1 Haste\n\nPrismatic Socket\nSocket Bonus: + 2 Agility\n\nDurability 100 / 100\nClasses: Shaman\nBattlegear of the Firebird (0/5)\nFirebird's Spaulders\nFirebird's Legguards\nFirebird's Helmet\nFirebird's Grips\nFirebird's Cuirass\nLegacy Set: Bonus is inactive\n(2) Set : Increases the damage done by your Lava Lash ability by 15%.\n(4) Set : Increases the critical strike chance bonus from your Stormstrike ability by an additional 15%.\nSell Price:" }
