entries[87212] = { ["name"] = "Breath of the Black Prince", ["text"] = "Binds when picked up\nUse: Greatly empower any piece of Sha-Touched equipment. Removes all existing gems and enchants.\n1 Charge\n\"The powers of the last black dragon are yours to wield.\"" }
entries[87213] = { ["name"] = "Mist-Piercing Goggles", ["text"] = "Binds when equipped\nHead\nEquip: Allows you to see additional mining nodes and herbs while in Pandaria.\n\"While these goggles are very fashionable, they don't need to be worn to receive their special benefit.\"\nSell Price:" }
entries[87214] = { ["name"] = "Blingtron 4000", ["text"] = "Binds when picked up\nToy\nUse: Assembles the incredible Blingtron 4000, a robot of infinite wealth. Bling, as he likes to be called, will give out a random gift to anyone who talks to him, but only once per day. Lasts 10 min. (4 Hrs Cooldown)\nRequires Pandaria Engineering (75)" }
entries[87215] = { ["name"] = "Wormhole Generator: Pandaria", ["text"] = "Binds when used\nToy\nUse: Teleports you to somewhere in Pandaria. The exact location is difficult to predict, but will likely be far away. (15 Min Cooldown)\nRequires Pandaria Engineering (1)\n\"There is a tiny note on the side: Wheeeeeeeeeee!\"\nSell Price:" }
entries[87216] = { ["name"] = "Thermal Anvil", ["text"] = "Use: Places a Thermal Anvil at your feet, granting anyone nearby the use of both an anvil and a forge. Lasts 5 min. (5 Min Cooldown)\n20 Charges\nSell Price:" }
