entries[87250] = { ["name"] = "Depleted-Kyparium Rocket", ["text"] = "Unique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nThe apex of goblin ingenuity! This mount changes depending on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"When Kyparite is depleted of its amber essence it becomes fairly resistant to the corrosion from rocket fuel.\"\nProfession:\nEngineering" }
entries[87251] = { ["name"] = "Geosynchronous World Spinner", ["text"] = "Unique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nA device that rotates the very world beneath you! This mount changes depending on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"This rocket was originally designed to speed up the rotation of the world making for shorter nights. Gnomes with insomnia can have lofty goals.\"\nProfession:\nEngineering" }
